import Link from "next/link"; import Image from "next/image"; import { notFound } from "next/navigation"; import { AppShell } from "@/components/AppShell"; import { PreviewGate } from "@/components/PreviewGate"; import { ModuleBreadcrumb, ModulePager } from "@/components/ModuleNav"; import { modules, lessonHref } from "@/data/curriculum"; import { ReadAloud } from "@/components/ReadAloud"; import { MarkComplete } from "@/components/Tracking";
// Full-width illustration placed inside a lesson body, right after the section it illustrates.
// Animated images (.webp/.gif) skip Next's optimizer, which would flatten them to one frame.
function LessonFigure({src,alt,caption}:{src:string;alt:string;caption?:string}){return <figure className="lesson-figure"><Image src={src} alt={alt} width={1672} height={941} unoptimized={/\.(webp|gif)$/.test(src)} sizes="(max-width: 900px) 100vw, 760px" style={{width:"100%",height:"auto",borderRadius:12,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}}/>{caption&&<figcaption>{caption}</figcaption>}</figure>}
const content:Record<string,{kicker:string;title:string;lead:string;body:React.ReactNode;image?:string;image2?:string;image3?:string}>={
 "why-we-hesitate":{kicker:"Lesson 1 of 6",title:"Why We Hesitate",lead:"Call reluctance is not laziness. It is your brain trying to protect you from an uncertain social outcome.",body:<><h2>The pause before the call</h2><p>You know who to call. You know roughly what to say. Yet suddenly checking email, researching the account one more time, or reorganizing the CRM feels urgent. That is the avoidance loop at work.</p><LessonFigure src="/lesson-why-we-hesitate.png" alt="A rep at his desk while email, research and CRM tasks pull his attention away from the call" caption="Email, one more round of research, CRM cleanup: anything but the dial." /><blockquote>Call reluctance grows when avoiding the call produces immediate relief.</blockquote><h2>What is really happening?</h2><p>Your brain often treats a cold call as a social threat: you might be dismissed, challenged, or exposed as not knowing every answer. Avoidance briefly removes that discomfort, which teaches your brain to repeat the behavior.</p><h2>Why it actually hurts</h2><p>This isn&apos;t just a figure of speech. Neuroscientists Naomi Eisenberger and Matthew Lieberman found that social rejection activates the dorsal anterior cingulate cortex&mdash;the same brain region that processes physical pain. A dismissive &ldquo;not interested&rdquo; registers, briefly, as something closer to an injury than an inconvenience, which is part of why one bad call can sting more than the facts of the situation justify.</p><LessonFigure src="/lesson-why-we-hesitate-2.png" alt="Illustration of social rejection and physical pain lighting up the same region of the brain" caption="Rejection and physical pain activate the same brain region." /><p>It also gets weighted unfairly. Psychologist Roy Baumeister and colleagues documented what they called the negativity bias: across dozens of studies, people consistently give a single negative event more psychological weight than several neutral or positive ones. Nine calls that went fine and one that went badly rarely feel like a 9-to-1 day&mdash;they feel like &ldquo;a bad day,&rdquo; because the one bad call is doing most of the emotional work.</p><h2>The first reframe</h2><p>Your job is not to control whether a merchant is interested. Your job is to create enough relevant conversations to find the merchants who have a problem you can help solve. Knowing the sting is a documented, universal brain response&mdash;not a personal weakness&mdash;is itself part of what makes it easier to dial through.</p></>},
 "fear-of-rejection":{kicker:"Lesson 2 of 6",title:"Fear of Rejection",lead:"A merchant rejecting a conversation is responding to timing, relevance, and circumstance—not issuing a verdict on you.",body:<><h2>Rejection feels personal</h2><p>Cold calling puts your request directly in front of another person. When they say no, your nervous system can interpret it as social rejection even though the merchant is making a business decision with limited information.</p><blockquote>“No” is an outcome from one moment—not a measurement of your worth or potential.</blockquote><h2>Separate identity from outcome</h2><p>Instead of saying “I was rejected,” use precise language: “That merchant did not agree to a conversation today.” Accuracy matters. It keeps one call from becoming a story about your ability.</p><h2>Why the reframe changes the feeling, not just the words</h2><p>This isn&apos;t simply positive self-talk. Psychologist James Gross&apos;s research on emotion regulation shows that cognitive reappraisal&mdash;deliberately changing how you describe or interpret a situation&mdash;measurably reduces activity in the brain&apos;s threat-response circuitry, compared with suppressing the feeling or just gritting through it. Swapping &ldquo;I got rejected&rdquo; for &ldquo;that merchant didn&apos;t agree to a conversation today&rdquo; isn&apos;t a euphemism; it&apos;s a documented technique for lowering the actual emotional charge of the event, not just how you talk about it afterward.</p><h2>Measure the controllable</h2><p>You control preparation, dials, tone, questions, follow-up, and reflection. You do not control timing, current contracts, competing priorities, or another person&apos;s mood.</p><LessonFigure src="/lesson-fear-of-rejection.png" alt="A rep surrounded by what he controls (notes, dials, questions, follow-up) while timing, contracts and mood sit outside the circle" caption="Inside the circle: what you control. Outside it: what you don't." /></>},
 "sounding-inexperienced":{kicker:"Lesson 3 of 6",title:"Fear of Sounding Inexperienced",lead:"Sounding unsure on a call almost never comes from a knowledge gap—it comes from talking in generalities instead of specifics you actually trust.",body:<><h2>It is not what you know, it is what you can say out loud</h2><p>Most reps who freeze up on rate or technical questions actually know the material. The freeze happens live, on the phone, when a merchant asks something pointed and the rep reaches for an answer they have never said out loud before. Silence and hedging read as inexperience even when the underlying knowledge is fine.</p><blockquote>Confidence on a call is a rehearsal problem, not a competence problem.</blockquote><h2>Two well-documented effects at work</h2><p>The freeze itself has a name. Psychologists Pauline Clance and Suzanne Imes described the impostor phenomenon in 1978&mdash;the persistent feeling of being a fraud despite clear evidence of competence. It shows up constantly in strong performers, not just beginners, which is why tenure alone rarely makes it disappear on its own.</p><p>The fix has research behind it too. The testing effect&mdash;demonstrated repeatedly in memory research by Henry Roediger and Jeffrey Karpicke&mdash;shows that actually retrieving and saying information out loud builds far more durable, fluent recall than passively re-reading or reviewing it silently. Saying your answer to a rate objection out loud once, before you need it, is doing real cognitive work, not just “practicing.”</p><h2>Have one real number ready</h2><p>Before you dial, have at least one concrete figure in your pocket—an average effective rate, a typical savings range, a common statement line item merchants overpay on. One real number said plainly does more for your credibility than a well-organized script.</p><h2>Say it before you need it</h2><p>Practice your answer to the 2-3 questions merchants ask most—rates, contracts, switching hassle—out loud, before the call, not while composing it live for the first time in front of a prospect. The goal is not memorization, it is removing the moment of surprise.</p><LessonFigure src="/lesson-sounding-inexperienced.png" alt="A rep rehearsing rate, contract and switching answers out loud before making the call" caption="Say the answers out loud before the call, then take the call." /></>},
 "avoidance-loop":{kicker:"Lesson 4 of 6",title:"The Avoidance Loop",lead:"Avoiding a call gives you real, immediate relief—which is exactly what trains your brain to keep avoiding it.",body:<><h2>How the loop runs</h2><p>A dial feels uncertain, so you do something that feels productive instead: more research, CRM cleanup, one more warm callback. The discomfort drops immediately. Your brain logs that relief as a reward, and the substitute behavior gets a little more automatic the next time a hard call is due.</p><LessonFigure src="/lesson-avoidance-loop-2.png" alt="The avoidance loop: research, reorganizing, an easy warm call and relief, broken by a 5-minute timer that leads straight to a dial" caption="The loop runs on relief. A 5-minute cap breaks it." /><blockquote>The loop is not broken by willpower—it is broken by removing the substitute behaviors it runs on.</blockquote><h2>Why this isn&apos;t a willpower problem</h2><p>This exact mechanism has a name and a long research history. Psychologist O. Hobart Mowrer&apos;s two-factor theory of avoidance learning (1947) explains how avoidance behavior gets reinforced by the relief it produces, regardless of whether the feared outcome was ever likely to happen. The relief is real and immediate; the threat it&apos;s avoiding is often exaggerated or gone. That mismatch is exactly why avoidance can quietly grow stronger over time even as the actual risk of a bad call stays low.</p><p>It&apos;s the same mechanism clinical psychologists target in exposure therapy for anxiety and phobias: preventing the avoidance response, even briefly, is what lets the brain recalibrate how threatening a situation actually is. A cold call is a much lower-stakes version of the same pattern.</p><h2>Recognize the substitutes</h2><p>Research past a 5-minute cap, reorganizing a list that was already fine, or working the same three easy contacts instead of the cold ones—none of it is a dial, no matter how busy it feels.</p><h2>Break it with a hard boundary, not more motivation</h2><p>Time-box research to 5 minutes before the first attempt. Dial before you open email or touch the CRM. Put your coldest, highest-friction leads first in the day, when avoiding them takes the most active effort to justify.</p><LessonFigure src="/lesson-avoidance-loop.png" alt="Email and research locked while a 5-minute timer sends the rep straight to his coldest lead" caption="Lock the substitutes, cap research at 5 minutes, and call the coldest lead first." /></>},
 "the-call-block":{kicker:"Lesson 1 of 6",title:"Building Your Call Block",lead:"“I’ll make some calls today” is the easiest plan in the world to skip. A call block is a scheduled window with a defined job, not a vague intention.",body:<><h2>Three blocks, three jobs</h2><p>Split the day instead of leaving it open-ended. An AM block (60–90 minutes) works your freshest, coldest, highest-friction leads first, while willpower is highest. A midday block (30–45 minutes) is for callbacks and follow-ups only—no fresh prospecting. A PM block (60–90 minutes) is a second pass on the AM list: decision-makers who didn’t answer the first time often answer the second.</p><LessonFigure src="/lesson-the-call-block.png" alt="Three call blocks across the day: cold leads in the morning, callbacks at midday, a second pass in the afternoon" caption="AM, midday and PM blocks each have one job." /><blockquote>A call block is an appointment with yourself. You wouldn’t skip a meeting with your manager because the first ten minutes felt uncomfortable.</blockquote><h2>Protect the block</h2><p>Nothing else happens inside it—not email, not CRM cleanup, not “quick research.” Those are legitimate tasks, but they belong before or after the block, never inside it. The block only has one job: dialing.</p><h2>Use the Pomodoro Method inside longer blocks</h2><p>A 60–90 minute block of nothing but cold dials is a lot to sustain at full focus. Split it into 25-minute dial sprints with a strict 5-minute break between them—the classic Pomodoro structure. Set a timer, dial with full attention until it rings, then actually step away for the break instead of letting it bleed into a sixth call.</p><LessonFigure src="/lesson-the-call-block-2.png" alt="A 25-minute dial sprint, a 5-minute break, then another 25-minute sprint" caption="25-minute sprints with a real 5-minute break between them." /><blockquote>The break is what makes the next sprint full-intensity again. Skipping it to squeeze in one more call is how a 90-minute block quietly turns into 40 minutes of real focus and 50 minutes of fading energy.</blockquote><h2>Why the sprint structure works</h2><p>This isn&apos;t just a productivity trend. Sustained-attention research dating back to N.H. Mackworth&apos;s original radar-operator studies has repeatedly found that vigilance on a monotonous, effortful task reliably declines within about 20&ndash;30 minutes&mdash;a pattern researchers call the vigilance decrement. A scheduled break isn&apos;t a reward for reaching the timer; it&apos;s what lets attention actually reset before it decays further.</p><p>Two or three sprints comfortably fill an AM or PM block, with a natural, built-in stopping point if something urgent comes up—far easier to protect than one long undifferentiated stretch.</p></>},
 "setting-your-number":{kicker:"Lesson 2 of 6",title:"Setting a Real Daily Target",lead:"A goal that depends on how the morning went isn’t a goal—it’s a mood. Set the number before you dial, from your list size, not your feelings.",body:<><h2>Why “make some calls” fails</h2><p>A target with no number attached quietly shrinks the moment the first few calls go badly. There’s nothing to hold you to, so the day drifts into other tasks that feel productive without being a dial.</p><h2>Set it from the list, not the mood</h2><p>Pick a minimum daily dial count sized to your actual list—enough to reach every priority lead this week without over-calling anyone. Write it down before the first dial, and commit to it even if the first ten calls go badly.</p><LessonFigure src="/lesson-setting-your-number.png" alt="A rep turns his lead list into a daily target of 30 dials and writes the number down, ignoring his mood" caption="Size the number from your list, write it down, and leave your mood out of it." /><blockquote>The 11th call doesn’t know about the first 10. Whether it goes well has nothing to do with how the morning felt.</blockquote><h2>Vague goals reliably underperform specific ones</h2><p>This is one of the most replicated findings in organizational psychology. Edwin Locke and Gary Latham&apos;s goal-setting theory, built on decades of studies across a wide range of tasks, consistently found that specific, measurably-defined goals produce higher effort and performance than vague &ldquo;do your best&rdquo; goals&mdash;even when the specific goal is demanding. &ldquo;Make some calls&rdquo; is a do-your-best goal. A written number is not.</p><h2>Treat the number as non-negotiable</h2><p>A bad morning is a reason to keep the number, not shrink it—shrinking it on hard days is exactly how the number stops meaning anything.</p><LessonFigure src="/lesson-setting-your-number-2.png" alt="Call 11 of 30 with the target locked, after a string of no-answers" caption="Call 11 of 30. The target stays locked, whatever the first ten did." /></>},
 "the-precall-routine":{kicker:"Lesson 3 of 6",title:"A Pre-Call Routine That Removes Hesitation",lead:"Every decision you have to make right before dialing—who, what to say, whether you’re ready—is a fresh opening for hesitation. A routine removes the decisions.",body:<><h2>Hesitation lives in the gaps</h2><p>It’s rarely the call itself that gets skipped—it’s the ten seconds before it, where your brain gets a fresh chance to ask “am I really ready for this one?” The more decisions packed into that gap, the more chances to stall.</p><h2>The routine</h2><p>Run the same short sequence before every block, in the same order, so none of it requires a decision: pull today’s list and confirm the first name, glance at your answers to the 2–3 objections you hear most, say your opener out loud once, then dial immediately—no further prep after that.</p><LessonFigure src="/lesson-the-precall-routine.png" alt="The four-step pre-call routine: pull the list, glance at the 2-3 objection answers, say the opener out loud, then dial" caption="Pull the list, glance at your objection answers, say the opener out loud, dial." /><blockquote>A routine replaces willpower with habit. You don’t decide to start; you just run the sequence and the dial happens at the end of it.</blockquote><h2>Decision fatigue is real and measurable</h2><p>Roy Baumeister&apos;s research on ego depletion describes how the mental effort of making decisions draws down a limited resource over the course of a day. A striking real-world example: a 2011 study of Israeli parole judges found their rate of favorable rulings started high after each break, then dropped steadily toward zero as the session wore on, before jumping back up after the next break. Nothing about the cases changed&mdash;the judges&apos; capacity to weigh a fresh decision did.</p><LessonFigure src="/lesson-the-precall-routine-2.png" alt="A rep full of energy in the morning, drained and hesitating late in a session, then recharged after a short break" caption="Every decision draws down the tank. A routine and a real break refill it." /><p>A pre-call routine works the same way a scheduled break does for those judges: it removes decisions from the exact moments&mdash;right before a hard dial&mdash;when you have the least mental capacity left to make them well.</p><h2>Keep it identical every time</h2><p>The value is in the repetition, not the content—changing the routine daily just recreates the decision-making it’s meant to remove.</p></>},
 "activity-vs-outcome":{kicker:"Lesson 4 of 6",title:"Track Activity, Not Just Outcomes",lead:"A closed deal tells you what worked weeks ago. Dials, connects, and conversations tell you what’s happening today—while there’s still time to fix it.",body:<><h2>Outcomes lag activity</h2><p>Deals closed this week reflect calls made weeks ago, not today’s effort. If you only track outcomes, a real problem—reluctance, a bad list, a broken opener—can run for weeks before the numbers show anything is wrong.</p><LessonFigure src="/lesson-activity-vs-outcome.png" alt="A rep's dashboard showing 24 dials, 6 conversations and 3 next steps, leading weeks later to a closed deal" caption="Dials, conversations and next steps today. The closed deal shows up weeks later." /><h2>What to log, and when</h2><p>Dials attempted, conversations had, and next steps set are all controllable today. Log them in the CRM in real time, right after each call—not from memory at the end of the day, when half of it gets lost or rounded up.</p><blockquote>Logging a call takes 30 seconds. It is not the task you’re avoiding by putting it off—it just feels that way in the moment.</blockquote><h2>Leading indicators, not just lagging ones</h2><p>Performance management draws a standard distinction between lagging indicators&mdash;results you can only measure after the fact, like closed deals&mdash;and leading indicators&mdash;behaviors today that predict those results later, like dials and conversations. Psychologists Edward Deci and Richard Ryan&apos;s self-determination theory supplies the motivational half of the story: goals built around effort and behavior you actually control sustain motivation far better over time than goals tied only to outcomes you don&apos;t fully control.</p><p>Tracking dials and conversations isn&apos;t a consolation prize for not having closed deals yet&mdash;it&apos;s the metric that&apos;s still actually yours to move today.</p><h2>Why this matters beyond you</h2><p>Consistent activity logging is also what lets a manager coach the actual problem instead of guessing—see the Manager view for how this data turns into specific coaching, not vague encouragement.</p><LessonFigure src="/lesson-activity-vs-outcome-2.png" alt="A rep logs a call in 30 seconds while his manager reviews the same activity data to coach him" caption="Log each call in 30 seconds, and your manager can coach the real problem." /></>},
 "the-first-ten-seconds":{kicker:"Lesson 1 of 4",title:"The First Ten Seconds",lead:"Before a merchant hears your offer, they’ve already decided whether you’re worth another thirty seconds. The opener’s only job is to win that decision.",body:<><h2>What the merchant is deciding</h2><p>When a restaurant owner or store manager picks up, they’re answering three quick questions: Who is this? Why are they calling me? Is this worth another thirty seconds? If your first ten seconds don’t answer all three, the answer to the last one defaults to no.</p><LessonFigure src="/lesson-the-first-ten-seconds.png" alt="A merchant weighing three checkpoints on a cold call: who is this, why are they calling my business, and is it worth another thirty seconds" caption="Who is this? Why me? Is it worth thirty more seconds? Answer all three or the answer is no." /><blockquote>The opener doesn’t sell anything. It earns the next thirty seconds.</blockquote><h2>Snap judgments are fast, and they stick</h2><p>Psychologists Nalini Ambady and Robert Rosenthal found that people who watched just a few seconds of silent video of a teacher formed impressions that closely matched the end-of-semester ratings from students who had spent months in that class. Their 1993 study used clips as short as six seconds. Judgments formed in the first moments aren’t random, and they’re hard to shift afterward. On a cold call the merchant has even less to go on: your voice, your first sentence, and whether it sounds like it’s about them.</p><h2>A three-part opener</h2><p>Keep the structure fixed so you’re never improvising the part that matters most. First, who you are, in one breath: your first name and company. Second, why you’re calling them specifically: a real reason tied to their business. Third, a short question that’s easy to answer.</p><p>For example: “Hi Maria, it’s David with BytePOS. I’m calling because you opened the Atlantic Avenue location last month, and owners at that stage often end up running two different card systems. Did you keep the same processor for both?” That takes about twelve seconds, and every part answers one of the merchant’s three questions.</p><LessonFigure src="/lesson-the-first-ten-seconds-anim.webp" alt="Animated: a rep delivers his opener to a restaurant owner as it moves through who he is, a reason tied to the store, and a short question, inside a ten-second timer" caption="Who you are, why them, one easy question: about ten seconds." /><h2>What to cut</h2><p>“How are you today?” from a stranger tells the merchant it’s a sales call before you’ve said why you’re calling. So does a long company introduction. Everything before your reason is time the merchant spends deciding without the one piece of information that could make them say yes.</p></>},
 "a-reason-about-them":{kicker:"Lesson 2 of 4",title:"Give Them a Reason That’s About Them",lead:"“We help businesses save on processing” could be said to anyone, so it sounds like it’s being said to everyone. A specific reason tells the merchant this call is actually about them.",body:<><h2>Why a reason works at all</h2><p>In a classic 1978 study, Harvard psychologist Ellen Langer and her colleagues had someone ask to cut in line at a copy machine. With no reason given, 60% of people let them. Adding a reason, “because I’m in a rush,” raised that to 94%. Even a nearly empty reason, “because I have to make copies,” got 93%. For small requests, people respond to the presence of a reason almost automatically.</p><h2>On a cold call, the reason has to hold up</h2><p>The copy-machine requests were tiny and the stakes were low. A merchant getting their fifth processing call of the week is paying closer attention, and a generic reason gets filed with the other four. Giving a reason earns you the benefit of the doubt. A specific reason keeps it.</p><LessonFigure src="/lesson-a-reason-about-them.png" alt="A generic pitch broadcast to many restaurants and ignored, next to one specific reason routed to a single restaurant with two disconnected card systems" caption="A pitch sent to everyone gets filed with the others. A reason about one merchant gets heard." /><blockquote>If your reason would work for any business on your list, it isn’t a reason. It’s a category.</blockquote><h2>Where specific reasons come from</h2><p>You don’t need deep research, and the 5-minute cap from Module 1 still applies. One real observation is enough: a new or second location, a recent ownership change, a liquor license application, reviews that mention “cash only” or a card reader that’s always down, a cash-discount notice on the menu, or an older terminal visible in photos. For leads that came from a new-opening or permit signal, the signal that put them on your list is usually the reason.</p><h2>Turn the observation into a likely problem</h2><p>The observation on its own isn’t the reason. What it usually means for the merchant is. “You opened a second location” becomes “owners at that stage often end up with two systems that don’t talk to each other.” Say it as something that’s common, not something you’re accusing them of. You’re offering a guess they can confirm or correct, and either answer keeps the conversation going.</p><LessonFigure src="/lesson-a-reason-about-them-2.png" alt="A rep noticing a restaurant has two locations whose POS systems aren't connected" caption="The observation: a second location. The likely problem: two systems that don't talk to each other." /></>},
 "drop-the-apology":{kicker:"Lesson 3 of 4",title:"Drop the Apology and the Script Voice",lead:"“Sorry to bother you, I’ll be really quick” tells the merchant your call is an interruption before they’ve decided whether it is one.",body:<><h2>Apologizing for the call frames the call</h2><p>Openers like “sorry to bother you,” “I know you’re busy,” or “I’ll just take a second” are meant to sound polite. What they actually communicate is that you consider this call an imposition, and they invite the merchant to agree. You’re a professional calling about something that might help their business. Say so plainly and let them decide.</p><LessonFigure src="/lesson-drop-the-apology.png" alt="Split scene: an apologetic rep reading a script meets a closed-off merchant; the same rep speaking plainly with his notes gets an engaged merchant" caption="Reading an apology invites a no. Speaking plainly about their business invites a reply." /><blockquote>Polite and apologetic aren’t the same thing. Be the first without the second.</blockquote><h2>Plain words sound more credible, not less</h2><p>Psychologist Daniel Oppenheimer’s research on processing fluency found that writing full of unnecessarily complex words was judged to come from less intelligent authors than the same ideas written plainly. His 2006 paper made the point in its own title: “Consequences of Erudite Vernacular Utilized Irrespective of Necessity.” The same applies out loud. “We provide comprehensive, end-to-end payment solutions” is harder to process than “we set up card processing and POS systems for restaurants,” and whatever is harder to process comes across as less credible.</p><h2>Script voice is a delivery problem</h2><p>Reps who read an opener sound like they’re reading: an even pace, no pauses, and the same rise at the end of every sentence. Merchants hear that pattern all day and tune it out. The fix isn’t to drop the structure. It’s to know the three parts well enough to say them in your own words. That’s the rehearsal effect from Module 1: say your opener out loud until it sounds like something you’d actually say.</p><LessonFigure src="/lesson-drop-the-apology-2.png" alt="A flat, monotone script waveform fading out above a natural waveform with pauses, as a rep practices his opener out loud" caption="Script voice runs flat and even. Your own words have pauses and land." /><h2>End statements like statements</h2><p>Let your voice come down at the end of your name and your reason. A rising tone turns “It’s David with BytePOS” into a question, as if you’re asking permission to be on the call. Save the rise for the one real question at the end of your opener.</p></>},
 "ask-for-the-next-30-seconds":{kicker:"Lesson 4 of 4",title:"Ask for the Next 30 Seconds",lead:"The opener ends with a question the merchant can answer in a few words. The goal isn’t the appointment yet. It’s a conversation that keeps going.",body:<><h2>Close the opener with an easy question</h2><p>A good closing question is specific, about their business, and answerable without much thought: “Did you keep the same processor for both locations?” or “Are you still on the terminal that came with the space?” Avoid questions that are really a pitch, like “Would you like to save money on processing?”, and questions that invite a reflex no, like “Do you have a minute?”</p><blockquote>Ask something they can answer in five words. Every answer tells you where to go next.</blockquote><h2>Small yeses make bigger ones easier</h2><p>In a well-known 1966 study, psychologists Jonathan Freedman and Scott Fraser asked homeowners to put a large, unattractive “Drive Carefully” sign on their front lawn. Only about 17% agreed. But among homeowners who had agreed two weeks earlier to a much smaller request, displaying a three-inch safe-driving sign, about 76% agreed to the big one. This foot-in-the-door effect is why the opener aims small. A merchant who has answered one easy question about their setup has already started a conversation, and continuing it is the natural next step.</p><LessonFigure src="/lesson-ask-for-the-next-30-seconds.png" alt="A merchant answers one easy question about their terminal, the conversation continues, and it ends in a booked appointment" caption="One easy answer, then a conversation, then the appointment." /><h2>“Who is this?” and “What’s this about?”</h2><p>These aren’t objections. They’re the merchant asking for the things your opener should have covered. Answer directly and briefly, repeat your reason, and ask your question again. Getting defensive, or starting over with a longer pitch, turns a request for clarity into a reason to hang up.</p><h2>Know when the opener worked</h2><p>The opener worked if the merchant is talking about their business, even if what they say is “we’re happy with what we have.” That’s a conversation, and it’s your handoff to the rest of the call. The opener only failed if the call ended before they said anything about their business at all.</p><LessonFigure src="/lesson-ask-for-the-next-30-seconds-2.png" alt="A restaurant owner on the phone talking about his two locations while the rep listens, with a thirty-second timer between them" caption="The merchant is talking about their business. The opener did its job." /></>},
 "every-vertical-has-its-own-pain":{kicker:"Lesson 1 of 4",title:"Every Vertical Has Its Own Pain",lead:"A restaurant owner and an HVAC contractor both take cards, but they lose sleep over completely different things. Relevance starts with knowing which problems belong to which business.",body:<><h2>“Payments” isn’t one problem</h2><p>Reps who pitch the same benefits to every merchant are pitching the product, not the business. Lower rates and faster deposits matter to everyone, which is exactly why they don’t make anyone lean in. What earns attention is the problem that business runs into every week, said in a way that tells the owner you already understand how their day works.</p><blockquote>Rates are what every merchant has in common. Their real problem is what makes them different.</blockquote><h2>What each vertical tends to care about</h2><p><b>Restaurants:</b> tips and tip adjustments, splitting checks, speed at the counter during a rush, online ordering, and the commissions third-party delivery apps take, often 15% to 30% of an order. <b>Retail:</b> inventory that matches what actually sold, chargebacks, seasonal swings in volume, gift cards, and reporting across more than one location. <b>Service businesses</b> like salons, auto shops and contractors: getting paid on the job or in the field, cards on file, deposits and no-show fees, and chasing unpaid invoices. <b>E-commerce:</b> checkout friction, fraud and chargebacks, and card-not-present pricing, which usually runs higher than card-present.</p><p>Treat these as starting guesses, not facts about the merchant you’re calling. Their job is to make your first question a good one.</p><LessonFigure src="/lesson-every-vertical-has-its-own-pain.png" alt="A rep studying four panels: a busy restaurant, a clothing store, a contractor at his van, and an online shopper, each with its own list of problems" caption="Four verticals, four different problems. Start with the one that fits." /><h2>Timing is part of relevance</h2><p>Calling a restaurant at 12:15 or 6:30 tells the owner you don’t know their business before you’ve said a word. Most restaurants are easiest to reach in the mid-afternoon lull, roughly 2 to 4 p.m. Retail managers are often freer right after opening, before foot traffic builds. Contractors and other field businesses are usually reachable early, before they head out, or at the end of the day. Matching your call block to the vertical is the cheapest relevance you’ll ever get.</p><LessonFigure src="/lesson-every-vertical-has-its-own-pain-2.png" alt="A timeline of the day: a contractor reached early, a store manager after opening, a restaurant owner in the mid-afternoon lull, with the lunch and dinner rushes crossed out" caption="Call each vertical when they can actually talk: early for contractors, after opening for retail, 2 to 4 p.m. for restaurants." /><h2>Build a one-line cheat sheet per vertical</h2><p>For each vertical on your list, write one line: the two problems that come up most, and the best time to call. Keep it next to your pre-call routine from Module 2. It turns “what do I say to a salon?” from something you improvise live into something you decided ahead of time.</p></>},
 "speak-in-their-numbers":{kicker:"Lesson 2 of 4",title:"Speak in Their Numbers",lead:"“We can save you money” is abstract. “On a $40 average ticket, that’s about 30 cents a transaction” is something the owner can picture. Concrete beats clever.",body:<><h2>Concrete sounds true</h2><p>Psychologists Jochim Hansen and Michaela Wänke found in 2010 that people rated the same claim as more likely to be true when it was written in concrete language than in abstract terms. Nothing about the facts changed, only how easy they were to picture. On a cold call, abstract benefits like “efficiency,” “savings” and “better experience” slide straight past the merchant. Specifics stick, because the merchant can check them against their own business in their head.</p><blockquote>If the owner can’t picture it, they won’t believe it.</blockquote><LessonFigure src="/lesson-speak-in-their-numbers.png" alt="A rep turning a restaurant's $40 average ticket into a concrete figure of 30 cents per transaction while the owner listens" caption="“Savings” slides past. “About 30 cents on a $40 ticket” is something the owner can check in their head." /><h2>Use the units they already track</h2><p>Every vertical measures itself differently. Restaurants think in covers, average ticket and table turns. Retail thinks in average basket, transactions per day and shrink. Service businesses think in jobs per week and days until they get paid. E-commerce thinks in orders, conversion rate and chargebacks. Translate what you offer into their unit: not “faster funding” but “the money from Friday’s jobs in your account Saturday instead of Tuesday.”</p><h2>Small, honest math beats big claims</h2><p>You rarely know a merchant’s real numbers on the first call, and inventing them costs you credibility. Use ranges and ask them to fill in the gap: “Most places your size run somewhere around 800 to 1,200 transactions a month. Is that close for you?” Their answer gives you a real number to work with, and asking shows you understand how their business is measured. Never promise a specific savings figure before you’ve seen a statement.</p><h2>One number, then stop</h2><p>A single concrete figure lands. Three in a row sound like a pitch deck. Pick the one number that matters most to this vertical, say it plainly, and let the merchant react. If it’s wrong for them, they’ll correct you, and the correction is the start of discovery.</p><LessonFigure src="/lesson-speak-in-their-numbers-2.png" alt="Four panels for a restaurant, a store, a contractor and an online shop, each with its own numbers and one highlighted as the number that matters most" caption="Every vertical has its own numbers. Pick the one that matters most to this merchant and stop there." /></>},
 "lead-with-a-business-like-theirs":{kicker:"Lesson 3 of 4",title:"Lead With a Business Like Theirs",lead:"Merchants don’t want to be your first. A real example of a business like theirs does more than any feature list, as long as it’s true.",body:<><h2>People follow people like them</h2><p>In a 2008 study, Noah Goldstein, Robert Cialdini and Vladas Griskevicius tested hotel signs asking guests to reuse their towels. The standard environmental message got about 35% of guests to reuse towels. A message saying most guests at the hotel reused theirs raised that to about 44%. Saying most guests who had stayed in that same room did so pushed it to about 49%. The closer the comparison group was to the guest, the stronger the effect.</p><blockquote>“Businesses like yours” beats “businesses.” “The pizzeria two miles from you” beats both.</blockquote><h2>Make the comparison close</h2><p>The same principle applies on the phone. “We work with thousands of merchants” is the generic hotel sign. “We set up two other family-owned taquerias in Jacksonville this year” is the same-room sign. Match on what the owner identifies with: the type of business, the size, the city, or the situation they’re in, like a second location or a recent ownership change.</p><LessonFigure src="/lesson-lead-with-a-business-like-theirs.png" alt="A rep mentions a nearby taqueria to a taqueria owner, who looks interested" caption="Not “thousands of merchants.” A business like theirs, close by." /><h2>Only ever use real examples</h2><p>This works because it’s true. If you invent a customer, a result, or a nearby business that doesn’t exist, you’re lying to the merchant, and one follow-up question exposes it. Keep a short list of real accounts you or your team have set up, by vertical and area, and what changed for them in plain words. Check with your manager before you name a customer. When you don’t have a close match, describe the situation honestly: “Owners who just opened a second spot usually tell us the hardest part is…”</p><LessonFigure src="/lesson-lead-with-a-business-like-theirs-2.png" alt="Before a call to a salon owner, a rep picks a real, verified salon customer as his example and rejects an invented one" caption="Match on a real customer, never an invented one." /><h2>Keep it to one sentence</h2><p>The example supports your reason for calling. It doesn’t replace your question. One sentence, then back to the merchant: “We set up a salon on Atlantic Avenue last spring that was losing a few hundred a month to no-shows. Are you taking deposits when people book?”</p></>},
 "fit-the-software-they-run":{kicker:"Lesson 4 of 4",title:"Integrated Payments: Fit the Software They Already Run",lead:"Many merchants don’t think of themselves as buying payments. They think of themselves as running their salon software, their practice system, or their POS. Start there.",body:<><h2>The software comes first</h2><p>Salons book in scheduling software, auto shops write tickets in shop-management systems, restaurants live in their POS, and online stores run on their e-commerce platform. For these owners, payments are one feature inside a tool they already depend on. When payments are built into that tool, sales, tips, refunds and deposits reconcile on their own. When they aren’t, someone ends up retyping totals into a terminal and matching reports at the end of the day.</p><LessonFigure src="/lesson-fit-the-software-they-run.png" alt="A salon owner points to her booking software, one of several business apps (salon, auto shop, restaurant, retail), each with payments built in" caption="Start with the software they already run. Payments are one feature inside it." /><blockquote>Ask what software they run before you mention what you sell.</blockquote><h2>Why switching feels expensive</h2><p>Economists William Samuelson and Richard Zeckhauser coined the term status quo bias in 1988, after finding that people disproportionately stick with whatever option they already have, even when an alternative is at least as good. For a merchant, the software they run every day is the status quo. A pitch that sounds like “replace your system” asks them to fight that bias. A pitch that works with their system doesn’t.</p><h2>Ask about the software first</h2><p>“What are you using for booking?” or “What POS are you on?” is easy to answer, specific, and tells you almost everything about where you fit. If your payments integrate with their software, lead with that: nothing new to learn, and no more double entry. If they don’t, be honest about what would change and what they would get in return. Don’t promise an integration you haven’t confirmed.</p><h2>Listen for double entry</h2><p>The clearest sign of an integration problem is manual work: “My front desk types the total into the card machine,” or “I match the deposits to the tickets every Friday.” When you hear it, repeat it back in their words and ask how long it takes. That time is the business case, and it came from the owner, not from you.</p><LessonFigure src="/lesson-fit-the-software-they-run-2.png" alt="Left: a salon front desk retyping a total into a card machine and matching reports that don't agree. Right: payments built into the salon software, reconciling on their own" caption="Double entry on the left, integrated payments on the right. The time it costs is the business case." /></>},
 "discovery-not-interrogation":{kicker:"Lesson 1 of 4",title:"Discovery Is Not an Interrogation",lead:"Once the merchant starts talking, it’s tempting to run down a checklist. Ten questions in a row feels like an audit, and merchants end audits quickly.",body:<><h2>Why the checklist backfires</h2><p>On a cold call you haven’t earned much patience yet. Rapid-fire questions about their processor, their rates, their volume and when their contract ends make the merchant feel like they’re being qualified, which they are. Answers get shorter, and “just send me something” shows up soon after. Every question costs the merchant a little time and attention. They’ll keep answering only as long as the conversation gives them something back.</p><blockquote>Ask questions the merchant is glad you asked, not questions they’re putting up with.</blockquote><LessonFigure src="/lesson-discovery-not-interrogation.png" alt="Split scene: a rep firing a clipboard's worth of questions at a restaurant owner who sits with arms crossed, and the same rep asking one question with context while the owner leans in" caption="A checklist feels like an audit. One question with a reason behind it feels like a conversation." /><h2>Give a little before you ask</h2><p>Put a short piece of context in front of the question: “A lot of salons we talk to lose real money to no-shows. Do you take a card to hold appointments?” The context tells the owner why you’re asking, shows you know their world, and makes the question feel like it’s about their business instead of your form. It’s the same idea as the reason in your opener from Module 3.</p><h2>One question, then quiet</h2><p>Ask one question at a time. “Who do you process with, how long have you been with them, and are you happy?” lets the merchant pick the easiest part and skip the rest. After you ask, stop talking. A two-second pause feels long to you and normal to them, and the answer that comes after it is usually the more honest one.</p><h2>Keep it short on the phone</h2><p>A cold call isn’t the place for a full needs analysis. Three to five good questions is plenty. You’re trying to learn whether a meeting is worth both of your time, not everything about the business. The deeper discovery is what the appointment is for.</p></>},
 "ask-about-impact":{kicker:"Lesson 2 of 4",title:"Ask About Impact, Not Just Setup",lead:"“Who do you process with?” tells you their setup. “What happens when the card reader goes down on a Saturday?” tells you what the setup costs them. The second kind of question is where value comes from.",body:<><h2>What the research found</h2><p>Neil Rackham and his team at Huthwaite studied more than 35,000 sales calls over twelve years and published the results in <i>SPIN Selling</i> in 1988. Less successful sellers asked a lot of situation questions, the facts about the buyer’s current setup. More successful sellers asked fewer of those and spent more time on the buyer’s problems and what those problems led to. Buyers found long runs of situation questions tedious, because those questions serve the seller, not the buyer.</p><blockquote>Setup questions are for you. Impact questions are for them.</blockquote><LessonFigure src="/lesson-ask-about-impact.png" alt="A rep on a call with a restaurant owner, with panels showing a working terminal, the card reader failing, and a packed Saturday line of frustrated customers" caption="The terminal is the setup. The Saturday line when it goes down is the impact." /><h2>Three kinds of questions</h2><p><b>Setup</b> questions cover how they take payments today: processor, POS, terminals, online checkout. <b>Problem</b> questions ask what’s frustrating, slow or breaking. <b>Impact</b> questions ask what that problem costs in time, money or customers. A contractor example: “How long does it usually take to get paid once a job’s done?” is a problem question. “When it takes three weeks, what does that do to how you pay your crew and buy materials?” is an impact question. A restaurant example: “How much of your takeout comes through the delivery apps instead of your own site?” followed by “What does their cut add up to in a typical month?”</p><LessonFigure src="/lesson-ask-about-impact-2.png" alt="A rep talking with a contractor beside a work van, with panels tracing a finished job, a waiting invoice, a crew waiting to be paid, and materials on hold" caption="A slow payment isn’t just a date on an invoice. Ask what it does to the crew and the next job." /><h2>Do the setup homework before you dial</h2><p>A lot of setup questions can be answered before the call. The merchant’s website often shows their online ordering or booking provider, how many locations they have, and whether they sell online. Each fact you find is one less question you have to spend on the phone, and it frees the conversation for the questions that matter. Add a quick look-up to your pre-call routine from Module 2.</p><h2>Don’t lead the witness</h2><p>Impact questions aren’t traps. “Wouldn’t you agree you’re probably overpaying?” is a pitch with a question mark on the end, and merchants hear it that way. Ask honestly and accept the answer, including “It’s actually fine.” A merchant without a real problem is useful information too. It saves you an appointment that wasn’t going anywhere.</p></>},
 "follow-the-answer":{kicker:"Lesson 3 of 4",title:"Follow the Answer",lead:"The best discovery question usually isn’t on your list. It’s the one you build from what the merchant just said.",body:<><h2>Follow-up questions make you more likable</h2><p>In a 2017 study in the <i>Journal of Personality and Social Psychology</i>, Karen Huang, Alison Wood Brooks and colleagues at Harvard analyzed live conversations and found that people who asked more questions were liked more by the people they talked with. The effect came mostly from follow-up questions, the ones that build on what the other person just said. A follow-up shows you were listening in a way no scripted question can.</p><blockquote>A follow-up question is proof you were listening.</blockquote><h2>Three follow-ups that work almost anywhere</h2><p><b>Clarify their words:</b> “What do you mean by ‘all over the place’?” <b>Size it:</b> “How often does that happen?” <b>Get the history:</b> “What have you tried so far?” For example, if a store owner says the fees are all over the place, don’t move on to your next question. Ask: “All over the place how? Different every month, or just higher than you expected?” Their answer tells you far more than the question you were about to ask.</p><LessonFigure src="/lesson-follow-the-answer.png" alt="A store owner on a video call describing tangled, confusing fees while the rep branches the answer into three follow-ups: clarify, how often, and what they've tried" caption="“All over the place” is the start of the answer. Clarify it, size it, and ask what they’ve tried." /><h2>Listen for the loaded words</h2><p>Some words carry more than they seem to. “Honestly,” “nightmare,” “always” and “last time” usually point to a real frustration or a bad experience. So do mentions of a past processor, a new owner, a second location or a system they’re replacing. Jot them down as you hear them. They’re the best material you’ll get for a follow-up, and later for the appointment itself.</p><h2>Play it back before you move on</h2><p>Before you change topics, summarize what you heard in the merchant’s own words: “So if I’ve got this right, the fees jump around month to month and nobody’s ever explained why.” It checks your understanding, it gives them a chance to correct you, and it lets them hear their problem stated plainly. That summary is often the natural bridge to asking for the meeting.</p><LessonFigure src="/lesson-follow-the-answer-2.png" alt="A rep noting the merchant's loaded words in a notebook, playing them back, getting a confirmation, and moving to a calendar" caption="Write down the loaded words, play them back, and the summary becomes the bridge to the meeting." /></>},
 "what-the-appointment-needs":{kicker:"Lesson 4 of 4",title:"Know What the Appointment Needs",lead:"Discovery on a cold call has a finish line. Once you know there’s a real reason to meet and who needs to be in the room, stop digging and book it.",body:<><h2>The call isn’t the whole discovery</h2><p>The full analysis happens at the appointment, with a statement in hand and time to talk. On the call you only need enough to answer three questions: Is there a real reason to meet? Can this person make or influence the decision? What should the meeting cover? Keep digging past that point and you risk talking the merchant out of a meeting they were ready to take.</p><blockquote>Stop digging when you have a reason to meet. The rest of the discovery belongs in the meeting.</blockquote><h2>The short list</h2><p>Before you hang up, try to have four things. <b>A problem or goal in their words,</b> like the fees that jump around or the three-week wait to get paid. <b>Who decides:</b> the owner, a partner, a franchise’s corporate office, or the bookkeeper who reads the statements. <b>Anything that shapes timing,</b> such as a contract end date, an equipment lease, a new location opening, or a POS change. <b>A recent processing statement,</b> or at least agreement to have one ready for the meeting. Without a statement, nobody can honestly tell the merchant what they’d save.</p><LessonFigure src="/lesson-what-the-appointment-needs.png" alt="A rep with four checked-off cards for the problem, who decides, timing, and a statement, feeding into a calendar, with a shovel set down beside a check mark" caption="Problem, decision-makers, timing, statement. Once the short list is checked, put the shovel down and book it." /><h2>Ask about decisions without insulting anyone</h2><p>“Are you the decision-maker?” can sound like you’re checking whether they matter. Try “Besides you, who else would want to weigh in on something like this?” It gets the same information, respects the person you’re talking to, and helps you get everyone who matters into the meeting instead of hearing “I need to run it by my partner” afterward.</p><LessonFigure src="/lesson-what-the-appointment-needs-2.png" alt="A rep adding the merchant's partner to a video meeting and landing a confirmed time instead of a tentative one" caption="Ask who else should weigh in, and get them into the meeting instead of hearing about them afterward." /><h2>Be honest when there isn’t a fit</h2><p>Sometimes discovery shows there’s no meeting worth booking. They just signed a long contract with a steep cancellation fee, the problem you expected isn’t there, or the business is too small for what you offer. Say so, thank them, and set a date to check back. An honest “this isn’t the right time” builds the kind of reputation that gets you a warmer call later. Module 8 covers how to follow up without chasing.</p></>},
 "not-interested":{kicker:"Lesson 1 of 4",title:"When They Say “Not Interested”",lead:"Ten seconds into a call, the merchant hasn’t heard enough to decide anything. “Not interested” is usually a reflex that protects their time, not a verdict on what you offer.",body:<><h2>A reflex, not a decision</h2><p>Owners get sales calls every week, and “not interested” is the fastest way to end any of them. It comes out before they know who you are or why you called. That makes it information about timing and relevance, not a judgment of you or your offer. It’s the same idea as Module 1: a merchant brushing off a call is responding to their circumstances, not grading you.</p><blockquote>Your job isn’t to overcome the objection. It’s to earn one more honest answer.</blockquote><h2>Steady yourself first</h2><p>Hearing “no” quickly sets off a small jolt of stress, and stressed reps either rush or argue. In a 2007 study in <i>Psychological Science</i>, Matthew Lieberman and colleagues at UCLA found that when people put a feeling into words, activity in the amygdala, the brain’s alarm system, dropped. You can use that on the phone. Name it to yourself (“that’s a reflex, not a no”), take one beat of silence, then answer. The pause also tells the merchant you aren’t about to steamroll them.</p><h2>Acknowledge, then one easy question</h2><p>Don’t argue with the objection and don’t pretend you didn’t hear it. Agree with what’s true, give your reason in one line, and ask one question that’s easy to answer: “That’s fair, you weren’t expecting my call. Before I let you go, when did someone last walk you through your processing statement?” The question is low-stakes, it’s about their business, and any answer tells you something. If they give you a real answer, you’re back in discovery from Module 5.</p><h2>Know when to let go</h2><p>If the second answer is still no, take it. Thank them, ask whether it’s all right to check back in a few months, and end the call warmly. Pushing past two clear no’s rarely turns into an appointment, and it guarantees a cold reception the next time you call. A polite exit keeps the door open. Module 8 covers how to follow up without chasing.</p></>},
 "were-happy":{kicker:"Lesson 2 of 4",title:"“We’re Happy With Who We Have”",lead:"“Happy” usually means “not unhappy enough to deal with switching.” That’s a reasonable position, and you’ll get further by treating it as one.",body:<><h2>Why switching feels expensive</h2><p>In their 1979 work on prospect theory, Daniel Kahneman and Amos Tversky showed that losses loom larger than gains of the same size. Switching processors comes with losses the owner can picture right away: paperwork, new equipment, retraining staff, the risk that something breaks on a busy day. The savings are a maybe. Add the status quo bias from Module 4, and “we’re happy” is a completely rational answer, not stubbornness.</p><blockquote>You’re not asking them to switch. You’re asking for a second look.</blockquote><h2>Don’t attack their processor</h2><p>Criticizing the merchant’s current provider means criticizing their decision, and people defend their decisions. Take them at their word: “Good, that’s what you want from a processor.” Now you’re not an opponent, and the next question lands differently.</p><h2>Ask what “happy” covers</h2><p>Happy with the service isn’t the same as knowing the cost. Ask a question that separates the two: “If you could change one thing about how payments work for you, what would it be?” or “When did someone last compare your statement against what’s out there?” Pricing on a merchant account can change over its life, sometimes announced in a line on the statement that few owners read. You don’t need to claim that happened to them. You only need to ask whether anyone has checked.</p><h2>Offer a check-up, not a switch</h2><p>A small request is easier to agree to than a big one, and it makes the next step easier too. In a classic 1966 study, Jonathan Freedman and Scott Fraser found that homeowners who first agreed to a small request were far more likely to agree to a much bigger one later. Asking to review a statement is small: “No change needed. Let me look at your last statement, and if you’re getting a fair deal, I’ll tell you so.” Then keep that promise. Telling a merchant they’re in good shape is how you become the rep they call when something changes.</p></>},
 "send-me-information":{kicker:"Lesson 3 of 4",title:"“Just Send Me Some Information”",lead:"“Send me something” is often the politest way to end a call. Sometimes it’s real interest. One question tells you which.",body:<><h2>What it usually means</h2><p>Asking for information lets the merchant end the call without saying no. If you agree and hang up, you send a generic brochure, it lands in an inbox with dozens of others, and neither of you thinks about it again. It feels like progress, which is exactly why it’s easy to settle for.</p><blockquote>If they want information, find out which information. If they won’t say, they wanted off the call.</blockquote><h2>Agree, then narrow it</h2><p>Don’t push back on the request. Say yes, then ask what would make it worth reading: “Happy to. So I send something useful instead of a brochure, what matters most to you right now: what you’re paying, how fast you get funded, or how it works with your POS?” A merchant who’s genuinely interested will tell you, and their answer is discovery. One who wanted off the phone will stall, and that tells you where you stand.</p><h2>Tie it to a next step</h2><p>Information on its own doesn’t move anything forward. Attach a short, specific follow-up to it: “I’ll send it this afternoon. Can we take ten minutes Thursday morning to go over it together?” If they agree, you have an appointment in all but name. If they won’t commit to any next step at all, you’ve learned that without spending a week waiting on an email.</p><h2>Send what you promised</h2><p>When they do agree, send it the same day. Keep it short, make it about what they told you, and use their words: “You mentioned the fees change every month. Here’s how we’d show you exactly why.” A fast, specific follow-up is proof that you listened, and it sets up the next call.</p></>},
 "price-resistance":{kicker:"Lesson 4 of 4",title:"“What’s Your Rate?” and Price Pushback",lead:"Price comes up early on almost every merchant call. Quoting a number on the phone feels helpful, and it’s nearly always a mistake.",body:<><h2>Why a quoted rate misleads</h2><p>What a merchant actually pays depends on their card mix (debit, rewards and business cards cost different amounts), how cards are taken (tapped, keyed in, or online), and the pricing model on their account. A low headline rate can come with higher fees somewhere else. The honest comparison is the effective rate: total fees divided by total card volume, taken from a real statement. Anything else is a guess.</p><blockquote>Don’t compete on a number you haven’t earned the right to quote.</blockquote><h2>The first number sticks</h2><p>In a 1974 study, Amos Tversky and Daniel Kahneman had people spin a wheel rigged to land on 10 or 65, then estimate the percentage of African countries in the United Nations. People who saw 10 guessed a median of 25 percent. People who saw 65 guessed 45. A number they knew was random still pulled their answer. A rate you quote on the phone works the same way: it becomes the anchor the merchant measures everything against, including the next rep’s teaser rate.</p><h2>What to say instead</h2><p>Be straight with them: “Honestly, anyone who quotes you a rate without seeing your statement is guessing. What I can do is work out what you’re really paying now, then show you what it would be with us.” Then ask what they pay today. Most owners don’t know their effective rate, and saying so out loud makes the statement review an easy yes.</p><h2>When they say you’re too expensive</h2><p>Ask what they’re comparing against: “Too expensive compared to what?” Often it’s a rate someone quoted them or a flat rate from a card reader they bought at a store. Compare total cost, not headline rates, and don’t offer a discount on the phone to save the call. If you honestly aren’t cheaper, say so. Then talk about what you do better only if it’s real and matters to them, like next-day funding, local support or a POS integration. A rep who admits when they’re not the lowest price is a rep merchants believe about everything else.</p></>},
};
export default async function LessonPage({params}:{params:Promise<{slug:string;lesson:string}>}){const {slug,lesson}=await params;const module=modules.find(m=>m.slug===slug);if(!module)notFound();const data=content[lesson];if(!data)notFound();return <AppShell active="Training"><PreviewGate status={module.status}><div style={{padding:"35px 4vw 70px",maxWidth:1120,margin:"auto"}}><ModuleBreadcrumb moduleSlug={slug} itemId={lesson}/><div style={{display:"grid",gridTemplateColumns:"1fr 280px",gap:22}}><article className="card" style={{padding:"clamp(28px,5vw,60px)"}}><div className="eyebrow">{data.kicker}</div><ReadAloud targetId="lesson-audio-text" /><div id="lesson-audio-text"><h1 className="display" style={{fontSize:42,margin:"18px 0 20px"}}>{data.title}</h1><p style={{fontFamily:"Georgia,serif",fontSize:22,lineHeight:1.5,color:"var(--green)",marginBottom:28}}>{data.lead}</p><div className="lesson-copy">{data.body}</div></div><div style={{borderTop:"1px solid var(--line)",marginTop:45}}><ModulePager moduleSlug={slug} itemId={lesson}><MarkComplete moduleSlug={slug} itemId={lesson} minutes={module.lessons.find(l=>l.id===lesson)?.minutes??2}/></ModulePager></div></article><aside><div style={{position:"sticky",top:95}}><div className="card" style={{padding:22}}><div className="eyebrow">In this module</div><div style={{marginTop:15}}>{module.lessons.map((l,i)=><Link key={l.id} href={lessonHref(slug,l)} style={{display:"flex",gap:10,padding:"11px 0",borderTop:"1px solid var(--line)",fontSize:12,fontWeight:l.id===lesson?900:600,color:l.id===lesson?"var(--green)":"var(--muted)"}}><span>{i+1}.</span>{l.title}</Link>)}</div>{data.image&&<Image src={data.image} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}</div>{data.image2&&<Image src={data.image2} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}{data.image3&&<Image src={data.image3} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}</div></aside></div><style>{`.lesson-copy h2{font-family:Georgia,serif;font-size:29px;margin:35px 0 12px}.lesson-copy p{color:var(--muted);line-height:1.75;font-size:16px;margin:0 0 16px}.lesson-copy p:last-child{margin-bottom:0}.lesson-copy .lesson-figure{margin:26px 0 34px}.lesson-copy figcaption{margin-top:10px;font-size:13px;color:var(--muted);text-align:center}.lesson-copy blockquote{margin:30px 0;padding:24px 28px;border-left:5px solid var(--lime);background:#f2f6e7;font-family:Georgia,serif;font-size:21px;line-height:1.5}`}</style></div></PreviewGate></AppShell>}
